using System.IO.Pipes;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
namespace UnscRelay.Core;

public sealed record NativeRequest(string Token, string Action, string[] Arguments);
public sealed record NativeReply(bool Accepted, string Value = "");
public sealed class NativeBridge : IAsyncDisposable
{
    readonly CancellationTokenSource stop = new(); readonly Func<NativeRequest, Task<NativeReply>> handle; readonly Task run;
    readonly string token = Convert.ToHexString(RandomNumberGenerator.GetBytes(32));
    public string Name { get; } = "RelayNative-" + Guid.NewGuid().ToString("N");
    public NativeBridge(Func<NativeRequest, Task<NativeReply>> callback) { handle = callback; run = Serve(); }
    public void Apply(IDictionary<string, string> environment) { environment["RELAY_NATIVE_PIPE"] = Name; environment["RELAY_NATIVE_TOKEN"] = token; }
    async Task Serve() { while (!stop.IsCancellationRequested) { await using var pipe = new NamedPipeServerStream(Name, PipeDirection.InOut, 1, PipeTransmissionMode.Byte, PipeOptions.Asynchronous | PipeOptions.CurrentUserOnly); try { await pipe.WaitForConnectionAsync(stop.Token); using var timeout = CancellationTokenSource.CreateLinkedTokenSource(stop.Token); timeout.CancelAfter(TimeSpan.FromMinutes(2)); var request = JsonSerializer.Deserialize<NativeRequest>(await ReadLine(pipe, 32768, timeout.Token)); var reply = new NativeReply(false); if (request?.Token is { Length: 64 } && request.Action is { Length: > 0 and <= 32 } && request.Arguments != null && request.Arguments.Length <= 8 && request.Arguments.All(a => a != null && a.Length <= 16384) && CryptographicOperations.FixedTimeEquals(Encoding.ASCII.GetBytes(token), Encoding.ASCII.GetBytes(request.Token))) reply = await handle(request).WaitAsync(timeout.Token); var bytes = Encoding.UTF8.GetBytes(JsonSerializer.Serialize(reply) + "\n"); try { await pipe.WriteAsync(bytes, timeout.Token); await pipe.FlushAsync(timeout.Token); } finally { CryptographicOperations.ZeroMemory(bytes); } } catch (Exception ex) when (ex is IOException or OperationCanceledException or JsonException or ArgumentException or FormatException or InvalidOperationException or CryptographicException) { } } }
    static async Task<string> ReadLine(Stream stream, int limit, CancellationToken token) { using var data = new MemoryStream(); var b = new byte[1]; while (await stream.ReadAsync(b, token) > 0) { if (b[0] == 10) return Encoding.UTF8.GetString(data.ToArray()); data.WriteByte(b[0]); if (data.Length > limit) throw new IOException("Risposta nativa troppo lunga."); } throw new IOException("Canale nativo chiuso."); }
    public static async Task<int> RunHelper(string[] arguments) { var name = Environment.GetEnvironmentVariable("RELAY_NATIVE_PIPE"); var token = Environment.GetEnvironmentVariable("RELAY_NATIVE_TOKEN"); if (name == null || !name.StartsWith("RelayNative-", StringComparison.Ordinal) || token?.Length != 64 || arguments.Length < 1) return 1; try { using var timeout = new CancellationTokenSource(TimeSpan.FromMinutes(2)); await using var pipe = new NamedPipeClientStream(".", name, PipeDirection.InOut, PipeOptions.Asynchronous | PipeOptions.CurrentUserOnly); await pipe.ConnectAsync(timeout.Token); var request = new NativeRequest(token, arguments[0], arguments.Skip(1).ToArray()); await pipe.WriteAsync(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(request) + "\n"), timeout.Token); await pipe.FlushAsync(timeout.Token); var reply = JsonSerializer.Deserialize<NativeReply>(await ReadLine(pipe, 32768, timeout.Token)); if (reply?.Accepted != true) return 1; var bytes = Encoding.UTF8.GetBytes(reply.Value + "\n"); try { await using var output = Console.OpenStandardOutput(); await output.WriteAsync(bytes, timeout.Token); await output.FlushAsync(timeout.Token); } finally { CryptographicOperations.ZeroMemory(bytes); } return 0; } catch { return 1; } }
    public async ValueTask DisposeAsync() { stop.Cancel(); try { await run; } catch (OperationCanceledException) { } stop.Dispose(); }
}
public static class NativeIdentity
{
    public static (string PublicKey, string Algorithm, string Fingerprint) Parse(string text) { var parts = text.Trim().Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries); if (parts.Length < 2 || parts[0].Length > 120 || parts[1].Length > 16384 || parts[0].Any(c => !char.IsAsciiLetterOrDigit(c) && c is not ('-' or '@' or '.'))) throw new ArgumentException("Chiave pubblica nativa non valida."); var blob = Convert.FromBase64String(parts[1]); if (blob.Length < 8 || blob.Length > 12288) throw new ArgumentException("Chiave pubblica nativa non valida."); var length = System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(blob); if (length <= 0 || length > 120 || length > blob.Length - 4 || Encoding.ASCII.GetString(blob, 4, length) != parts[0]) throw new ArgumentException("Algoritmo della chiave non corrispondente."); return (parts[0] + " " + parts[1], parts[0], "SHA256:" + Convert.ToBase64String(SHA256.HashData(blob)).TrimEnd('=')); }
    public static string CanonicalAlgorithm(string algorithm) => algorithm is "rsa-sha2-256" or "rsa-sha2-512" ? "ssh-rsa" : algorithm;
    public static string KnownHost(NativeRequest request, HostKeyStore store, Func<HostKey, bool> confirm) { if (request.Arguments.Length != 6) throw new ArgumentException("Richiesta host incompleta."); var a = request.Arguments; var host = a[1]; if (host.Length is < 1 or > 256 || host.Any(char.IsWhiteSpace) || host.Any(char.IsControl) || !int.TryParse(a[2], out var port) || port is < 1 or > 65535 || a[3].Length is < 1 or > 300 || a[3].Any(char.IsWhiteSpace) || a[3].Any(char.IsControl)) throw new ArgumentException("Endpoint host non valido."); if (a[0] == "ORDER") return string.Join("\n", store.List().Where(k => k.Host.Equals(host, StringComparison.OrdinalIgnoreCase) && k.Port == port && k.PublicKey.Length > 0).Select(k => a[3] + " " + k.PublicKey)); if (a[0] is not ("HOSTNAME" or "ADDRESS")) throw new ArgumentException("Richiesta host non supportata."); var key = Parse(a[4] + " " + a[5]); if (key.Algorithm.Contains("-cert-", StringComparison.Ordinal)) throw new IOException("Certificato host nativo non supportato dal gestore condiviso: verifica una chiave host ordinaria."); var entry = new HostKey(host, port, key.Algorithm, key.Fingerprint[7..], DateTime.UtcNow, key.PublicKey); var state = store.Check(host, port, key.Algorithm, key.Fingerprint); if (state == HostKeyState.Changed) throw new IOException("CHIAVE HOST CAMBIATA: connessione rifiutata. Verifica il gestore host."); if (state == HostKeyState.Unknown && !confirm(entry)) throw new OperationCanceledException(); store.Accept(entry); return a[3] + " " + key.PublicKey; }
}
